    const historyDisabled = await startEngine(inner, 'u1', {enabled: false});
    const failingList = await startEngine({
      ...delegatingTo(inner),
      listFor: () => Promise.reject(new Error('database offline')),
    });

    const unimplemented = await askAfterConnect(withoutList, {type: 'list_conversations'});
    const disabled = await askAfterConnect(historyDisabled, {type: 'list_conversations'});
    const failed = await askAfterConnect(failingList, {type: 'list_conversations'});

    expect({
      unimplemented: unimplemented.frames.map(frame => ({type: frame.type, code: frame.code})),
      disabled: disabled.frames.map(frame => ({type: frame.type, code: frame.code})),
      failed: failed.frames.map(frame => ({type: frame.type, code: frame.code})),
      logged: logLines.filter(line => line.level === 'error' && line.category === 'ws'),
    }).toEqual({
      unimplemented: [{type: 'error', code: 'UNSUPPORTED'}],
