/** Tears every socket and server down, so a red test reports instead of hanging the run. */
export async function stopEngines(): Promise<void> {
  for (const client of clients.splice(0)) {
    try {
      client.terminate();
    } catch {
      // Ignored: a socket that never opened or already closed needs no further teardown.
    }
  }
  for (const hal of servers.splice(0)) {
    const server = hal as {wss?: {clients: Set<WebSocket>}; stop: () => Promise<void>};
    if (server.wss) await eventually(() => server.wss!.clients.size === 0);
    await hal.stop();
  }
}

